     1→"use strict";
     2→
     3→// Lowest Note Filter for Max4Live
     4→// Buffers simultaneous note-ons (within a time window) and passes
     5→// only the lowest pitch through. Note-offs for suppressed notes
     6→// are also suppressed.
     7→//
     8→// Inlet 0: note data [pitch, velocity] from midiparse (also accepts "reset")
     9→// Inlet 1: bang from delay (chord window expired)
    10→// Outlet 0: filtered note data [pitch, velocity] to midiformat
    11→// Outlet 1: timer control messages to delay object
    12→
    13→inlets = 2;
    14→outlets = 2;
    15→
    16→// pitch -> velocity for notes buffered in the current chord window
    17→let tempNotes = {};
    18→// pitch -> true for notes we actually sent (so we know which note-offs to forward)
    19→let sentNotes = {};
    20→
    21→function list() {
    22→	if (inlet === 0) {
    23→		const pitch = arguments[0];
    24→		const vel = arguments[1];
    25→
    26→		if (vel > 0) {
    27→			onNoteOn(pitch, vel);
    28→		} else {
    29→			onNoteOff(pitch);
    30→		}
    31→	}
    32→}
    33→
    34→function onNoteOn(pitch, vel) {
    35→	tempNotes[pitch] = vel;
    36→
    37→	// Restart the chord-detection window.
    38→	// stop cancels any pending delay, then bang starts a fresh one.
    39→	outlet(1, "stop");
    40→	outlet(1, "bang");
    41→}
    42→
    43→function onNoteOff(pitch) {
    44→	// If this pitch is still sitting in the temp buffer (window hasn't
    45→	// fired yet), remove it so it doesn't participate in chord detection.
    46→	if (pitch in tempNotes) {
    47→		delete tempNotes[pitch];
    48→	}
    49→
    50→	// Only forward the note-off if we actually sent the corresponding note-on.
    51→	if (pitch in sentNotes) {
    52→		outlet(0, pitch, 0);
    53→		delete sentNotes[pitch];
    54→	}
    55→}
    56→
    57→function bang() {
    58→	// Inlet 1: chord window timer fired — process buffered notes
    59→	if (inlet === 1) {
    60→		processWindow();
    61→	}
    62→}
    63→
    64→function processWindow() {
    65→	const pitches = Object.keys(tempNotes);
    66→	if (pitches.length === 0) return;
    67→
    68→	// Find the lowest pitch
    69→	let lowestPitch = Number(pitches[0]);
    70→	let lowestVel = tempNotes[lowestPitch];
    71→
    72→	for (let i = 1; i < pitches.length; i++) {
    73→		const p = Number(pitches[i]);
    74→		if (p < lowestPitch) {
    75→			lowestPitch = p;
    76→			lowestVel = tempNotes[p];
    77→		}
